// ---------------------------------------------------------------------------
// Marketplace Taxonomy
//
// Single source of truth for all category and tag definitions across the
// platform. No business logic lives here - this module is a constants and
// typing contract only.
//
// Design principles:
//   - Categories are stable, broad, and intentionally limited in count.
//     They drive search, analytics, and Zod enum validation.
//   - Tags are flexible string arrays generated by Gemini at listing time.
//     They evolve as the marketplace grows without requiring schema rewrites.
//   - All arrays are declared `as const` so TypeScript can narrow them to
//     literal tuple types, which is required by z.enum() in consuming routes.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Marketplace types
// ---------------------------------------------------------------------------

export const MARKETPLACE_TYPES = ["services", "goods"] as const;

export type MarketplaceType = (typeof MARKETPLACE_TYPES)[number];

// ---------------------------------------------------------------------------
// Service categories
//
// Reflects how Nigerian informal economy workers describe and search for help.
// Categories are deliberately broad to reduce AI misclassification and remain
// stable as platform usage scales.
// ---------------------------------------------------------------------------

export const SERVICE_CATEGORIES = [
  "Cleaning & Laundry",
  "House Maintenance & Repairs",
  "Yard Work & Landscaping",
  "Shopping & Errands",
  "House Sitting & Pet Care",
  "Local Marketing & Distribution",
  "Delivery & Running Around",
  "Domestic Help & Chores",
  "Other Tasks",
] as const;

export type ServiceCategory = (typeof SERVICE_CATEGORIES)[number];

// ---------------------------------------------------------------------------
// Goods categories
//
// Covers physical products listed on the goods side of the marketplace.
// Kept intentionally separate from service categories so both sides of
// the marketplace can evolve their taxonomies independently.
// ---------------------------------------------------------------------------

export const GOODS_CATEGORIES = [
  "Fashion & Clothing",
  "Beauty Products",
  "Accessories & Jewelry",
  "Electronics",
  "Phone Accessories",
  "Other Goods",
] as const;

export type GoodsCategory = (typeof GOODS_CATEGORIES)[number];

// ---------------------------------------------------------------------------
// Unified category union
//
// Used when a function or schema must accept any category regardless of
// marketplace type - for example, a shared search index or analytics query.
// ---------------------------------------------------------------------------

export type AnyCategory = ServiceCategory | GoodsCategory;

// ---------------------------------------------------------------------------
// Tag contract
//
// Tags are AI-generated at listing creation time and stored alongside the
// stable category. They are not validated against a fixed enum - their value
// comes from being flexible and evolving with real marketplace behaviour.
//
// Constraints enforced at the route layer:
//   - Array length: 1 to MAX_TAGS_PER_LISTING
//   - Each tag: lowercase string, no special characters
//   - Deduplication handled before persistence
// ---------------------------------------------------------------------------

export const MAX_TAGS_PER_LISTING = 8;
export const MIN_TAGS_PER_LISTING = 1;

/** Lowercase, trimmed string representing a single AI-generated tag. */
export type ListingTag = string;

// ---------------------------------------------------------------------------
// Prompt-ready category strings
//
// Pre-formatted for direct injection into Gemini system prompts.
// Keeps prompt construction in route files clean - no formatting logic needed
// at call time, just import and interpolate.
// ---------------------------------------------------------------------------

export const SERVICE_CATEGORIES_PROMPT_LIST = SERVICE_CATEGORIES.join(", ");
export const GOODS_CATEGORIES_PROMPT_LIST = GOODS_CATEGORIES.join(", ");
